from pysat.card import CardEnc

# Try integer encoding values
for enc in range(10):
    try:
        clauses = CardEnc.atleast(lits=[1,2,3,4,5], bound=3, top_id=100, encoding=enc)
        print(f"encoding {enc}: {len(clauses)} clauses")
    except Exception as e:
        print(f"encoding {enc}: error {e}")
